import os
import hmac
import hashlib
import time
import sqlite3
from flask import Flask, request, jsonify, g
import bcrypt

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
app.config['DATABASE'] = '/tmp/secure_app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        api_key TEXT UNIQUE
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        owner_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        classification TEXT NOT NULL DEFAULT 'public',
        FOREIGN KEY (owner_id) REFERENCES users(id)
    )''')
    db.commit()
    db.close()

def generate_api_key(user_id):
    timestamp = str(int(time.time()))
    payload = f"{user_id}:{timestamp}"
    signature = hmac.new(
        app.config['SECRET_KEY'],
        payload.encode(),
        hashlib.sha256
    ).hexdigest()
    return f"{payload}:{signature}"

def verify_api_key(api_key):
    """Verify API key and return user_id if valid."""
    try:
        parts = api_key.split(':')
        if len(parts) != 3:
            return None
        user_id, timestamp, provided_sig = parts
        payload = f"{user_id}:{timestamp}"
        expected_sig = hmac.new(
            app.config['SECRET_KEY'],
            payload.encode(),
            hashlib.sha256
        ).hexdigest()
        # Use constant-time comparison to prevent timing attacks
        if hmac.compare_digest(provided_sig, expected_sig):
            return int(user_id)
        return None
    except (ValueError, TypeError):
        return None

def get_authenticated_user():
    """Extract and verify user from request."""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return None
    user_id = verify_api_key(api_key)
    if user_id is None:
        return None
    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE id = ? AND api_key = ?',
        (user_id, api_key)
    ).fetchone()
    return user

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = data['username']
    password = data['password']

    if len(username) < 3 or len(username) > 50:
        return jsonify({'error': 'Invalid username length'}), 400
    if len(password) < 8:
        return jsonify({'error': 'Password too short'}), 400

    password_hash = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)',
            (username, password_hash, 'user')
        )
        db.commit()
        return jsonify({'message': 'User registered'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username taken'}), 409

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?',
        (data['username'],)
    ).fetchone()

    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401

    if not bcrypt.checkpw(data['password'].encode('utf-8'), user['password_hash'].encode('utf-8')):
        return jsonify({'error': 'Invalid credentials'}), 401

    api_key = generate_api_key(user['id'])
    db.execute('UPDATE users SET api_key = ? WHERE id = ?', (api_key, user['id']))
    db.commit()

    return jsonify({'api_key': api_key}), 200

@app.route('/api/documents', methods=['GET'])
def list_documents():
    user = get_authenticated_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    # Users can see their own documents and public documents
    docs = db.execute(
        'SELECT id, title, classification, owner_id FROM documents WHERE owner_id = ? OR classification = ?',
        (user['id'], 'public')
    ).fetchall()

    return jsonify({'documents': [dict(d) for d in docs]}), 200

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    user = get_authenticated_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    doc = db.execute(
        'SELECT * FROM documents WHERE id = ?',
        (doc_id,)
    ).fetchone()

    if not doc:
        return jsonify({'error': 'Not found'}), 404

    # Authorization check: user can access their own docs or public docs
    # Admins can access all documents
    if doc['owner_id'] != user['id'] and doc['classification'] != 'public':
        if user['role'] != 'admin':
            return jsonify({'error': 'Forbidden'}), 403

    return jsonify(dict(doc)), 200

@app.route('/api/documents', methods=['POST'])
def create_document():
    user = get_authenticated_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    classification = data.get('classification', 'public')
    if classification not in ('public', 'private', 'secret'):
        return jsonify({'error': 'Invalid classification'}), 400

    db = get_db()
    db.execute(
        'INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)',
        (user['id'], data['title'], data['content'], classification)
    )
    db.commit()
    return jsonify({'message': 'Document created'}), 201

@app.route('/api/admin/users', methods=['GET'])
def admin_list_users():
    user = get_authenticated_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    if user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    db = get_db()
    users = db.execute('SELECT id, username, role FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]}), 200

@app.route('/api/admin/promote', methods=['POST'])
def admin_promote():
    user = get_authenticated_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    if user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    data = request.get_json()
    if not data or 'user_id' not in data:
        return jsonify({'error': 'Missing user_id'}), 400

    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', ('admin', data['user_id']))
    db.commit()
    return jsonify({'message': 'User promoted'}), 200

@app.route('/api/user/profile', methods=['PUT'])
def update_profile():
    user = get_authenticated_user()
    if not user:
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data'}), 400

    allowed_fields = ['username']
    updates = {}
    for field in allowed_fields:
        if field in data:
            updates[field] = data[field]

    if not updates:
        return jsonify({'error': 'No valid fields'}), 400

    db = get_db()
    for field, value in updates.items():
        db.execute(
            f'UPDATE users SET {field} = ? WHERE id = ?',
            (value, user['id'])
        )
    db.commit()
    return jsonify({'message': 'Profile updated'}), 200

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000)
